    ['Tensile strength', ['2.37 N/mm² (EXCEED); 0.95 (101A-NB); 2.00 (CLIO NEO)', '1.5 (Sikaflex-11 FC+); 3.8 (PU 45 FT)', '1.9 (dumb-bell) / 0.75 (joint assembly)', '1.5 (MS45); < 0.5 (Mycoflex); 0.70 (NB-LM)', 'not published', 'not published']],
    ['Elongation at break', ['1,135 % (EXCEED); 771 % (101A-NB); 243 % (CLIO NEO)', '700 % (Sikaflex-11 FC+, PU 45 FT)', '700 % (dumb-bell) / 380 % (joint assembly)', '500 % (MS45); > 600 % (MS600); > 500 % (Mycoflex); 540 % (NB-LM)', 'not published', 'not published']],
    ['Hardness (Shore A)', ['15 (EXCEED); 16 (101A-NB); 50 (CLIO NEO)', '37 (Sikaflex-11 FC+); 40 (PU 45 FT)', '29', '43 (MS45); 32 (MS600); about 24 (Mycoflex)', '15–20', 'about 22']],
    ['Elastic recovery', ['> 90 % (EXCEED); > 86 % (101A-NB; JIS 85 %)', 'not published', 'not published', '> 70 % (Mycoflex); 58 % (NB-LM); JIS classes 25 / 20 require ≥ 60 %', 'not published', 'plastic (P)']],
    ['Weathering and durability (hours)', ['SWOM 6,000 h no abnormality (EXCEED, CLIO NEO; about 30 years by the manufacturer\'s conversion); 12,000 movement cycles; 101A-NB durability class 9030', '"good resistance to weathering" (Sika), "UV resistance excellent" (Mapei) — no hours', 'silicone itself weathers well, no hours; oil staining is the visible ageing', '"very high resistance to weathering and ageing" (MC), "excellent" (Mapei) — no hours; NB-LM 8020', '"high resistance to ageing" — no hours', 'may discolour under UV (Sika TDS)']],
    ['Non-staining (plasticiser, silicone oil)', ['plasticiser-free (perfect non-bleed); EXCEED adds the CR oligomer against early tack; CLIO NEO has no staining ingredient', 'plasticised sealants bleed with time: tacky paint, dust, blackened joints †', 'silicone oil bleeds: water-repellent staining on porous substrates (concrete, marble, granite — stated in the DOWSIL TDS)', 'NB types do not bleed; standard types are plasticised †', 'plasticised †', '—']],
    ['Paintable', ['yes: 101A-NB excellent paint adhesion and wide compatibility (rigid paints may crack); EXCEED yes, with the manufacturer\'s paint-adhesion list; CLIO NEO not with other makers\' paints', 'Sika: elastic sealants should not be overpainted (paints have limited movement); Mapei: elastomeric paint after full cure', 'no', 'yes, elastomeric paint after full cure (Mapei Elastocolor)', 'limited †', 'yes (check compatibility)']],
    ['Clear option', ['CLIO NEO: colourless, non-yellowing, letters readable through 10 mm; no staining ingredient', 'none', 'clear silicone: goes cloudy when thick, stains', 'clear MS (Mapeflex MS Crystal etc.) †', 'none', 'none']],
    ['Primer', ['dedicated OP-2019 / OP-2020: 100 ml in the box; adheres without primer but strongly recommended; other makers\' primers untested (outside the warranty)', 'Sika Primer-3 N / Aktivator-205 / Primer-215 (separate); Mapei Primer A / M / P', 'usually none (DOWSIL 791)', 'primer on porous substrates: Primerseal / Actiprimer (MS45); Primer MS2 required (MS600); Mycoflex 251', 'Primer 4 / 7 / 13 (by substrate, immersion)', 'none']],
    ['Tack-free', ['5 h (23 °C), 24 h (5 °C); CLIO NEO 3 h', '70 min (Sikaflex-11 FC+); 35 min (PU 45 FT)', '30 min', '35 min (MS45); 2–3 h (MS600); 30 min (Mycoflex); 1.5 h (NB-LM)', 'initial cure 24 h (25 °C)', '20 min']],
    ['Full cure', ['3–7 days (23 °C), 17–21 days (5 °C); waterproofing effect after 7 days', '3.5 mm / 24 h (Sika); 8.5 mm / 7 days (Mapei)', '4 mm / 3 days', '3 mm / 24 h, 7.5 mm / 7 days (MS45); immersion after 14 days (MS600)', '1 week (25 °C), 3 weeks (15 °C)', '2 mm / 24 h']],
    ['Application temperature, environment', ['0 °C and above (method statement); warranty checklist 5–35 °C, RH ≤ 80 %; no alcohol vapours (no silicone / MS the same day)', '+5 to +40 °C', '+5 to +40 °C', '+5 to +35 °C (MS45); 5–50 °C (MS600); +5 to +40 (Mycoflex)', '5–50 °C', '+5 to +35 °C (substrate ≤ 30)']],
    ['Components, mixing', ['one component, straight from the cartridge', 'one component', 'one component', 'one component', 'two parts: 5.5 L base + 0.5 L curing agent, 5 minutes slow mixing; pot life 2 h', 'one component']],
    ['Packaging', ['320 ml × 10 (with 100 ml primer, 10 nozzles, brush); 6 L pail × 2 (with 4 primer cans, 2 brushes); 600 ml sausage × 20 (101A-NB)', '300 ml cartridge; 600 ml sausage', '310 ml cartridge; 600 ml sausage', '300 ml × 12; 600 ml × 20 (MS45); 600 ml × 10 (MS600); 600 ml × 12 (Mycoflex)', '6 L two-part pack', '300 ml × 12']],
    ['VOC, registrations', ['JSIA F☆☆☆☆ (EXCEED JSIA-001019, CLIO NEO JSIA-001026, 101A-NB JSIA-001018); solvent-borne (ventilate, no flames)', 'EMICODE EC1PLUS (Sika); solvent-free (Mapei)', '—', 'EMICODE EC1 Plus (MS45, Mycoflex); solvent- and isocyanate-free', '—', 'water-based']],
    ['Third-party tests, standards', ['101A-NB: ASTM C920 Class 50 (SGS Kaohsiung 2020, GSL 2014, PSB 2004), CNS 6985 (SGS 2014), JIS A 5754 / CNS 8904 / potable-water leaching (SGS 2019, Changbin WTP); JIS A 5758 F-12.5E-9030 (CE0308034)', 'ISO 11600 F-25 HM, ASTM C920 Class 35 (PRO-3); F20 HM (PU 45 FT)', 'ISO 11600-F&G 25LM', 'ISO 11600 F20 / F25 HM; ASTM C920 Class 25; BS 6920 potable (MS600); DIN 18540 (Mycoflex); JIS F-12.5E-8020 (NB-LM)', '—', '—']],
    ['Warranty', ['EXCEED: 10-year project-limited material warranty (30-year service life is the design value); countersigned by Good Startup for Taiwan', 'per manufacturer', 'per manufacturer', 'per manufacturer', 'per manufacturer', 'per manufacturer']]
