SL_STEPS.en = {
  planS: { tag: 'Planning', title: 'Survey: the existing sealant and the joint geometry', short: 'Identify the existing sealant and its ageing (hard, shrunk, cracked, peeled), whether the joint has widened as the panels shrank, and the state of the panel edges; decide the extent of the re-sealing.', overview: 'Renewal of fibre-cement siding joints means removing the existing sealant completely and re-sealing. The survey looks at four things: the type of the existing sealant (silicone types affect the curing of the new one), its ageing, the joint width (a 10 mm joint at construction may have widened with shrinkage — extra backer rod restores two-sided adhesion) and the water uptake and ageing of the panel edges.', points: ['Record the type of the existing sealant: silicone / modified-silicone and polyurethane on different days.', 'Measure width and depth: the warranted range is 10–20 mm wide, 8–15 mm deep.', 'Where removal is impossible (window perimeters, internal corners) only overlaying is possible — outside the warranty; tell the owner beforehand.', 'Take the joint length into the quotation on this page.'], src: 'Standard method statement R03 §1, §3' },
  checkS: { tag: 'Before starting', title: 'Weather, materials and the site record', short: 'Fine or overcast; 0 °C or above and humidity 85 % or below (warranty checklist: 5–35 °C, ≤ 80 %); no dust-raising wind. Colour, quantity and primer to hand; the site record form prepared.', overview: 'Step 01: check the weather (fine or overcast; 0 °C or above, humidity 85 % or below; mind the wind) and the materials (colour and quantity as specified; primer to hand), and prepare the site record form. The warranty checklist is stricter: 5–35 °C, relative humidity 80 % or below, no rain and no undried dew.', points: ['Fine or overcast; no risk of rain.', '0 °C or above, humidity 85 % or below (method statement); checklist: 5–35 °C, ≤ 80 % RH.', 'Colour and quantity as specified; primer OP-2019 to hand.', 'Site record and checklist prepared.'], warning: 'No materials other than those specified; the warranty covers non-working joints only.', src: 'Standard method statement R03 step 01; site record and checklist' },
  removeS: { tag: 'Removal', title: 'Removing the existing sealant', short: 'Cut along both faces with a knife, pull the sealant out, shave the residue off the panel edges with a screwdriver or similar; three-sided adhesion is scraped off with a flat screwdriver.', overview: 'Step 02: remove the existing sealant with a utility knife; use a grinder, screwdrivers and the like where needed to remove it completely; scrape off three-sided adhesion with a flat screwdriver. Existing sealant or primer left on the panel edges lowers the bond and causes peeling — shave the edges thinly and remove it carefully.', points: ['Cut along both faces of the sealant.', 'Pull the sealant out with a screwdriver or similar.', 'Remove the residue on the edges carefully (shave thin).', 'Where removal is impossible (frame perimeters): partial removal and overlaying (outside the warranty).'], warning: 'Old sealant and old primer left behind cause peeling.', src: 'Standard method statement R03 step 02' },
  cleanS: { tag: 'Cleaning', title: 'Cleaning the joint', short: 'Brush off cuttings and dirt; no dirt, oil or moisture may remain on the adhesion faces. No alcohol-bearing solvents.', overview: 'Step 03: remove cuttings and dirt with a brush. Dirt, oil or moisture left on the adhesion faces causes the sealant to peel. Solvents containing alcohol stop the sealant curing — forbidden.', points: ['Brush off cuttings and dust.', 'Adhesion faces free of dirt, oil and moisture.', 'No alcohol-bearing solvents.'], warning: 'Alcohol-bearing solvent → poor cure of the polyurethane.', src: 'Standard method statement R03 step 03' },
  cleanW: { tag: 'Cleaning', title: 'Cleaning the frame perimeter', short: 'Dust, oil and moisture removed from the frame and the panel edges; protective film peeled off the frame; no alcohol-bearing solvents.', overview: 'New window perimeter: peel the protective film off the frame, brush the dust off the adhesion faces (aluminium frame, panel edge); treat oil with an alcohol-free cleaner †; check it is dry.', points: ['Adhesion faces free of dirt, oil and moisture.', 'Protective film removed †.', 'No alcohol-bearing solvents.'], practice: [1], src: 'Standard method statement R03 step 03; general practice †' },
  cleanP: { tag: 'Cleaning', title: 'Cleaning concrete, PCa and ALC joints', short: 'Release agent, laitance and dust brushed out of the joint; ground to a sound face where needed †; dry and oil-free.', overview: 'The adhesion faces of concrete and PCa panels often carry release agent and laitance: brush off the dust, grind to a sound face where needed †. A damp substrate releases water vapour during the cure and blisters or bursts the sealant — make sure it is completely dry.', points: ['Brush off dust and laitance; grind where needed †.', 'Check it is dry and oil-free.', 'No alcohol-bearing solvents.'], warning: 'Damp substrate → blistering and bursting of the sealant (TDS).', practice: [0], src: 'TDS important notes; standard method statement R03 step 03' },
  cleanV: { tag: 'Cleaning', title: 'Cleaning around the penetration', short: 'Dust and oil removed from the flange of the vent cap, louvre or box and the wall around it; check the material (coated aluminium ◎, PVC ◎, stainless steel △).', overview: 'The materials around penetrations vary: check them against the adhesion table of the TDS (coated aluminium, PVC board and FRP ◎; stainless steel △). Remove dust and oil, check it is dry.', points: ['Flange and wall free of dust and oil.', 'Material checked against the OP-2020 adhesion table.', 'No alcohol-bearing solvents.'], src: 'CLIO NEO TDS adhesion table' },
  cleanQ: { tag: 'Cleaning', title: 'Cleaning joints in water structures', short: 'Laitance and oil brushed out of the joint; work only once it is completely dry — a damp concrete blisters the sealant.', overview: 'Joints in water treatment plants, tanks and culverts are usually damp: let the substrate dry completely first (water vapour from a damp substrate blisters and bursts the curing sealant), then brush off laitance and dust.', points: ['Brush off laitance and dust; remove oil.', 'Work only when completely dry.', 'No alcohol-bearing solvents.'], warning: 'Make sure the substrate is completely dry before the work (TDS).', src: 'TDS important notes' },
  backerS: { tag: 'Backer rod', title: 'Backer rod: joint geometry and two-sided adhesion', short: 'Check width and depth; set the depth with the backer rod (10–20 mm wide → 8–15 mm deep, depth ≤ width, ≥ 5 mm thick) and secure two-sided adhesion at the same time; replace old bond breakers.', overview: 'Step 04: check that the joint width and depth are right. The warranted geometry: width 10 mm or more and 20 mm or less, depth 8 mm or more and 15 mm or less (depth never more than width; allowing for the relief of the siding and the tooling, the sealant must be at least 5 mm thick) — set with the backer rod. The rod adjusts the geometry and secures two-sided adhesion in one. Old bond breakers are peeled off and replaced. Working joints must have two-sided adhesion: three-sided adhesion causes splitting and peeling; where the panels have shrunk and the joint widened, fill the gap with backer rod to keep the adhesion two-sided.', points: ['Measure width and depth; correct first if outside the range.', 'Press the rod to the required depth.', 'No three-sided adhesion (working joints); also applicable to non-working joints.', 'Add rod where the joint has widened.'], warning: 'Sealant less than 5 mm thick is outside the warranty.', src: 'Standard method statement R03 step 04' },
  backerW: { tag: 'Backer rod', title: 'Backer rod round the frame', short: 'Backer rod between frame and cladding sets the depth and secures two-sided adhesion; continuous round the corners.', overview: 'The joint round the frame fails at the corners first: run the rod continuously round the corners, depth by width (10–20 mm wide → 8–15 mm deep).', points: ['Rod continuous round the four corners.', 'Depth ≤ width, ≥ 5 mm thick.'], src: 'Standard method statement R03 step 04' },
  backerP: { tag: 'Backer rod', title: 'Backer rod in a wide joint', short: 'The 20 mm PCa / RC joint: rod diameter about 1.3 × width †, pressed to 15 mm depth; two-sided adhesion.', overview: 'A 20 mm movement joint: the depth is held to 15 mm with the rod (depth never more than width); rod diameter about 1.3 times the joint width †, pressed in without twisting or tearing its skin †.', points: ['Diameter about 1.3 × width †.', 'Pressed to 15 mm depth; level.', 'Two-sided adhesion.'], practice: [0, 1], src: 'Standard method statement R03 step 04; general practice †' },
  tapeS: { tag: 'Masking', title: 'Masking tape', short: 'Tape that leaves no adhesive; tight to the joint edge and pressed down; pressed into the relief so it does not lift; only once the faces are dry.', overview: 'Step 05: use a tape that leaves no adhesive on the faces; press it tight to the joint edge; press it into the relief of the pattern so it does not lift; work only once the faces are dry. Tape set too far from the edge leaves a thin film of sealant that whitens on decorative joints.', points: ['Tape that leaves no adhesive.', 'Tight to the edge, pressed down, no lifting.', 'Only on dry faces.'], src: 'Standard method statement R03 step 05' },
  tapeV: { tag: 'Masking', title: 'Masking round the penetration', short: 'Tape along the flange and the wall leaving about 10 mm of fillet width; curves in short lengths †.', overview: 'The width of a clear termination must be even: one run of tape along the flange edge and one on the wall, leaving the fillet width (about 10 mm); round vent caps are taped in short lengths †.', points: ['Even fillet width.', 'Curves in short lengths †.'], practice: [1], src: 'Standard method statement R03 step 05; general practice †' },
  primeS: { tag: 'Primer', title: 'Dedicated primer OP-2019', short: 'Always OP-2019; on faces free of dirt and oil and dry, applied evenly without streaks or misses; dry 15 minutes or more (30 in winter); re-prime if not gunned the same day or wetted.', overview: 'Step 06: the primer OP-2019 must be used (range: fibre-cement siding, resin frames, aluminium frames). Apply once the faces are free of dirt and oil and fully dry; no streaks, no misses, no gaps. Dry 15 minutes or more (30 minutes or more in winter) = open time. If the sealant could not be gunned the same day, or the faces got wet from rain before gunning, re-prime once they are dry. Coverage reference: dip the brush once for every 50 cm run on one side.', points: ['Use {OP2019}.', 'Even, no streaks or misses; nothing beyond the faces.', 'Dry ≥ 15 min (winter ≥ 30 min).', 'Not gunned the same day, or wetted → re-prime.', 'PP and PE do not bond; not to be used.'], ordered: true, warning: 'Primer not dry, or too much → solvent vapour blisters and bursts the sealant.', src: 'Standard method statement R03 step 06; OP-2019 TDS' },
  primeN: { tag: 'Primer', title: 'Dedicated primer OP-2020 (101A-NB)', short: 'The dedicated primer OP-2020 (or OP-2019) of 101A-NB: applied evenly on dry faces, filled after 15–30 minutes of drying.', overview: '101A-NB adheres without primer, but the primer is strongly recommended for complete adhesion: every substrate in the TDS adhesion table takes OP-2020 or OP-2019. Drying 15–30 minutes.', points: ['Use {OP2020} (or {OP2019}).', 'Even, no misses.', 'Fill after 15–30 min of drying.'], ordered: true, warning: 'Primer not dry, or too much → blistering and bursting of the sealant.', src: '101A-NB TDS substrate preparation; OP-2020 TDS' },
  primeC: { tag: 'Primer', title: 'Dedicated primer OP-2020 (CLIO NEO)', short: 'The dedicated primer OP-2020 of CLIO NEO: applied evenly on coated aluminium, PVC, FRP and the like, dry 15–30 minutes.', overview: 'The properties of CLIO NEO are all measured with the OP-2020 primer (H-piece, failure mode CF). Apply evenly on dry faces, fill after 15–30 minutes.', points: ['Use {OP2020}.', 'Even, no misses.', 'Dry 15–30 min.'], ordered: true, src: 'CLIO NEO TDS; OP-2020 TDS' },
  fillS: { tag: 'Filling', title: 'Filling with EXCEED', short: 'Check the primer\'s open time has passed; nozzle on the bottom of the joint, gun continuously without a break; the right amount, no air.', overview: 'Step 07: check that the open time after priming has passed; hold the nozzle tip on the bottom of the joint and gun continuously without interruption; fill the right amount without trapping air. The sealant must reach the bottom of the joint with no voids inside or beneath — air or moisture in a void expands and blisters or bursts the sealant.', points: ['Primer open time passed.', 'Nozzle on the bottom, continuous gunning.', 'Right amount, no air, no voids.', 'Use up an opened cartridge the same day.'], warning: 'Voids → blistering and bursting.', src: 'Standard method statement R03 step 07; TDS' },
  fillW: { tag: 'Filling', title: 'Filling round the frame', short: 'Gun continuously along the four sides, no break at the corners; the head first †; nozzle on the bottom of the joint.', overview: 'Frame perimeter: nozzle on the bottom of the joint, gun continuously along the four sides, no break at the corners, no air.', points: ['Continuous round the corners.', 'Right amount, no air.'], src: 'Standard method statement R03 step 07' },
  fillP: { tag: 'Filling', title: 'Filling a wide joint', short: '20 mm joint: nozzle on the face of the backer rod, gunned slowly and continuously to fill without voids; 15 mm deep.', overview: 'A wide joint traps air beside the rod: hold the nozzle on the rod face and gun slowly so the sealant fills from the bottom up.', points: ['Nozzle on the rod face.', 'Slow and continuous, full to the tape.'], src: 'Standard method statement R03 step 07' },
  fillN: { tag: 'Filling', title: 'Filling with 101A-NB', short: 'Once the primer is dry, nozzle on the bottom of the joint, gunned continuously with no voids; a joint to be painted only needs smoothing.', overview: 'Filling 101A-NB follows the same rules as EXCEED: continuous gunning without voids once the primer is dry; the standard joint is 8–15 mm deep and 10–20 mm wide, depth never more than width.', points: ['Continuous gunning, no voids.', '10–20 mm wide, 8–15 mm deep.'], src: '101A-NB TDS important notes' },
  fillC: { tag: 'Filling', title: 'Filling with CLIO NEO', short: 'A fillet of about 10 × 10 mm gunned continuously round the flange; clear even when thick.', overview: 'CLIO NEO stays transparent at 10 mm — a fillet thick enough for reliable waterproofing can be gunned without thinning it for the sake of clarity.', points: ['Continuous gunning all round.', 'Fillet about 10 × 10 mm.'], src: 'CLIO NEO catalogue' },
  fillQ: { tag: 'Filling', title: 'Filling joints in water structures', short: 'Once the primer is dry, gun continuously with no voids; 15 mm deep; water only after 7 days of full cure.', overview: 'Joints that meet water: fill without voids (water in a void after immersion causes peeling); the TDS requires 7 days of cure for the full waterproofing effect.', points: ['Continuous gunning, no voids.', 'Cure 7 days (23 °C) before the water.'], src: '101A-NB TDS' },
  toolS: { tag: 'Tooling', title: 'Tooling: two passes', short: 'First pass presses the sealant to the bottom, drives the air out and beds it on the faces; the second smooths the surface. Too little pressure means poor adhesion.', overview: 'Step 08: tooling is done in two passes — the first presses the sealant in, the second smooths the surface, and the finish is clean. Press well towards the bottom of the joint to close gaps and drive the air out; bed the sealant evenly on the adhesion faces to secure the bond. Insufficient pressure leaves it off the faces and the adhesion poor.', points: ['First pass: press in, drive out the air.', 'Second pass: smooth.', 'Press well towards the bottom.'], warning: 'Too little pressure → poor adhesion.', src: 'Standard method statement R03 step 08' },
  toolV: { tag: 'Tooling', title: 'Tooling the fillet', short: 'The fillet pressed into an even triangular section bedded on flange and wall; bubbles show in a clear sealant — the first pass must be thorough.', overview: 'Bubbles and voids show in a clear sealant: the first pass must drive the air out thoroughly, the second smooths an even triangular section.', points: ['First pass: press in, drive out the air.', 'Second pass: even section.'], src: 'Standard method statement R03 step 08' },
  untapeS: { tag: 'Tape off', title: 'Removing the masking tape', short: 'Pulled carefully before the skin forms, without soiling the surroundings; pulled after skinning, the sealant strings and the joint edge is spoiled.', overview: 'Step 09: remove the tape carefully before the surface of the sealant cures, without soiling the surroundings. Removed once the skin has formed, the thickened sealant strings and the finish of the joint edge is spoiled.', points: ['Before the skin forms.', 'Without soiling the surroundings.'], warning: 'Tape off after skinning → stringing, spoiled edge.', src: 'Standard method statement R03 step 09' },
  paintN: { tag: 'Painting', title: 'Painting over the sealant', short: 'A one-component polyurethane cures from the surface and its skin time varies greatly with the season — paint only after it has cured through, longer in winter; elastomeric paint, adhesion checked first.', overview: '§6: EXCEED / 101A-NB are one-component polyurethane sealants that react with atmospheric moisture and cure from the surface; the surface curing (drying) time varies greatly with the season (temperature, humidity) and takes long in winter — paint only after the sealant has cured sufficiently. Paint over a sealant may crack immediately or with time: depending on the sealant-and-paint combination, adhesion may be low or the paint surface tacky — check before use. 101A-NB takes most paints, but a paint without elasticity may crack from the softness and movement of the sealant.', points: ['Paint after sufficient cure; longer in winter.', 'Elastomeric paint; trial the adhesion.', 'Rigid paint → cracked film.'], src: 'Standard method statement R03 §6; 101A-NB TDS' },
  inspS: { tag: 'Inspection', title: 'Inspection, cleaning and the site record', short: 'Sealant and primer on the wall face wiped off with a cloth before they cure; joints full, no voids, no misses; the site record and checklist filled in (LOT, joint sizes, primer, finished photographs).', overview: 'Step 10: wipe sealant and primer off the wall face with a cloth before they cure — insufficient wiping leads to discolouration and dirt. Complete the record of the warranty at the same time: sealant colour number, LOTs and quantities, primer LOTs and cans, photographs showing the LOTs, joint width and depth measured and photographed at several places, primer application photographed at several places, finished work photographed at several places, remarks.', points: ['Wipe off before curing.', 'Visual check: full, no voids, no misses, no bubbles.', 'Site record and checklist filled in and signed.'], src: 'Standard method statement R03 step 10; site record and checklist' },
  inspV: { tag: 'Inspection', title: 'Inspecting the clear termination', short: 'Bubbles, voids and misses are visible in a clear sealant; sealant on the surroundings wiped off before it cures.', overview: 'CLIO NEO is transparent: bubbles and voids show, and they are the weak points of the seal. Inspect, then wipe the surroundings before curing.', points: ['No bubbles, no voids.', 'Wipe off before curing.'], src: 'Standard method statement R03 step 10' },
  cureS: { tag: 'Curing', title: 'Curing', short: 'Tack-free 5 h (23 °C) / 24 h (5 °C); full cure 3–7 days / 17–21 days; the full waterproofing effect needs 7 days. No rain on the working day.', overview: 'One-component moisture-curing: the cure needs contact with atmospheric moisture. Tack-free 5 hours (23 °C), 24 hours (5 °C); full cure 3–7 days (23 °C), 17–21 days (5 °C); allow 7 days of cure for the full waterproofing effect. Longer in the cold; plan painting and water after full cure.', points: ['Tack-free 5 h / 24 h.', 'Full cure 3–7 days / 17–21 days.', 'Full waterproofing effect: 7 days.'], src: 'EXCEED / 101A-NB TDS application data' },
  cureQ: { tag: 'Curing', title: 'Curing before the water: 7 days', short: 'No water contact before full cure; the TDS requires 7 days of cure for the full waterproofing effect; longer in the cold.', overview: 'Joints that meet water: cure 7 days (23 °C) before filling; at 5 °C full cure takes 17–21 days.', points: ['Water after 7 days (23 °C).', 'Longer in the cold, to full cure.'], src: '101A-NB TDS' },
  planW: { tag: 'Planning', title: 'Window perimeters: right the first time', short: 'Frame material (anodised, coated, resin) and the adhesion of the panel edge checked; joint 10–20 mm wide; in renewals only overlaying is possible.', overview: 'The joint round the window takes the most rain, and in renewals it can rarely be removed completely (forcing it damages the surrounding parts) — only partial removal and overlaying, outside the warranty. Leaving 10–20 mm of joint and using the right primer at construction is the best value.', points: ['Material against the OP-2019 table: anodised aluminium ◎, coated aluminium ◎, PVC ◎.', 'Joint 10–20 mm wide, 8–15 mm deep.', 'Renewal: partial removal and overlaying (outside the warranty).'], src: 'Standard method statement R03 §3 case 01; OP-2019 TDS' },
  planP: { tag: 'Planning', title: 'PCa / RC joints: the movement and the edge of the warranty', short: 'Width and expected movement (within ±25 %) of the movement and induced joints; non-working joints are warranted, curtain-wall working joints are a design matter.', overview: 'EXCEED is intended for the working (movement) joints and concrete induced joints of all kinds of buildings; the manufacturer\'s project-limited warranty covers non-working joints (RC structural joints and the like), not working joints such as curtain walls. Design: joint 10–20 mm wide, expected movement within ±25 %, OP-2019 on concrete.', points: ['Expected movement ≤ ±25 %.', '10–20 mm wide, 8–15 mm deep.', 'Warranty: non-working joints; working joints separately.'], src: 'EXCEED TDS; standard method statement R03 §1; warranty' },
  planA: { tag: 'Planning', title: 'Joints to be painted: 101A-NB', short: 'ALC and concrete joints that will be painted over: the plasticiser-free 101A-NB (excellent paint adhesion); painting after the sealant has cured.', overview: 'A plasticised sealant can bleed, get tacky and collect dust within months of painting and ruin the look of a whole facade. 101A-NB has no plasticiser, excellent paint adhesion and wide paint compatibility — the standard answer for joints to be painted. ALC is △ for the primer; keep it in mind in the design.', points: ['101A-NB with OP-2020.', 'Paint after sufficient cure; elastomeric paint.', 'ALC: adhesion △, trial first †.'], practice: [2], src: '101A-NB catalogue and TDS' },
  planV: { tag: 'Planning', title: 'Penetrations: clear terminations', short: 'Materials of vent caps, louvres, ducts and boxes checked; CLIO NEO needs no colour matching; a day after any modified-silicone work.', overview: 'CLIO NEO is a highly transparent, highly weather-resistant exterior sealant for the waterproofing of louvres, vent caps, ducts and electrical boxes; not for cladding panel joints (243 % elongation). Materials against the OP-2020 table; a day or more after modified-silicone work on site.', points: ['Materials: coated aluminium ◎, PVC ◎, FRP ◎, stainless steel △.', 'Not for panel joints.', 'A day or more after modified-silicone.'], src: 'CLIO NEO catalogue and TDS' },
  planQ: { tag: 'Planning', title: 'Water structures: evidence first', short: 'Joints that meet drinking water: the SGS potable-water contact tests (2019) and the ASTM C920 Class 50 reports of 101A-NB go straight into the submittal; 7 days of cure before the water.', overview: '101A-NB passed the SGS staining (JIS A 5754), ozone (CNS 8904) and potable-water leaching tests for the Changbin water treatment plant, and was tested to ASTM C920-11 Class 50 for the Taipei MRT Circular Line CF640 culvert joints. Attach the reports to the specification; cure 7 days before the water.', points: ['Reports: SGS HV-19-00384, GSL PO-14-01052C, SGS KZ-19-00945.', '10–20 mm wide, 8–15 mm deep.', '7 days of cure before the water.'], src: 'SGS / GSL test reports; 101A-NB TDS' }
};
SLV_T.en = { classes: SLT.en['sl.vs.classes'], rows: SLT.en['sl.vs.rows'], rowsH: SLT.en['sl.vs.rowsH'], bars: SLT.en['sl.vs.bars'], aud: SLT.en['sl.vs.aud'], honest: SLT.en['sl.vs.honest'], src: SLT.en['sl.vs.src'], label: SLT.en['sl.vs.label'], title: SLT.en['sl.vs.title'], sub: SLT.en['sl.vs.sub'], fair: SLT.en['sl.fair'], cardH: SLT.en['sl.vs.cardH'], tag: SLT.en['sl.vs.tag'], vsTag: SLT.en['sl.vs.vsTag'], kpi: SLT.en['sl.vs.kpi'], barsLow: SLT.en['sl.vs.barsLow'], barsHigh: SLT.en['sl.vs.barsHigh'], barsAlt: SLT.en['sl.vs.barsAlt'], barsNA: SLT.en['sl.vs.barsNA'], matrixTitle: SLT.en['sl.vs.matrixTitle'], matrixSub: SLT.en['sl.vs.matrixSub'] };


